CREATE TABLE IF NOT EXISTS foosball.tenants (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(150) NOT NULL UNIQUE,
    slug VARCHAR(100) NOT NULL UNIQUE,
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO foosball.tenants (id, name, slug)
VALUES (1, 'Ramsey Solutions', 'ramsey-solutions')
ON CONFLICT (id) DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('foosball.tenants', 'id'),
    GREATEST((SELECT COALESCE(MAX(id), 1) FROM foosball.tenants), 1),
    true);

ALTER TABLE foosball.players ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.games ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.rating_history ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.tournaments ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.tournament_registrations ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.tournament_matches ADD COLUMN IF NOT EXISTS tenant_id BIGINT;
ALTER TABLE foosball.tournament_standings ADD COLUMN IF NOT EXISTS tenant_id BIGINT;

UPDATE foosball.players SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.games SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.rating_history SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.tournaments SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.tournament_registrations SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.tournament_matches SET tenant_id = 1 WHERE tenant_id IS NULL;
UPDATE foosball.tournament_standings SET tenant_id = 1 WHERE tenant_id IS NULL;

ALTER TABLE foosball.players ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.games ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.rating_history ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.tournaments ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.tournament_registrations ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.tournament_matches ALTER COLUMN tenant_id SET NOT NULL;
ALTER TABLE foosball.tournament_standings ALTER COLUMN tenant_id SET NOT NULL;

ALTER TABLE foosball.players DROP CONSTRAINT IF EXISTS players_name_key;
CREATE UNIQUE INDEX IF NOT EXISTS uk_players_tenant_name ON foosball.players (tenant_id, name);

ALTER TABLE foosball.players ADD CONSTRAINT fk_players_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.games ADD CONSTRAINT fk_games_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.rating_history ADD CONSTRAINT fk_rating_history_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.tournaments ADD CONSTRAINT fk_tournaments_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.tournament_registrations ADD CONSTRAINT fk_registrations_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.tournament_matches ADD CONSTRAINT fk_matches_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
ALTER TABLE foosball.tournament_standings ADD CONSTRAINT fk_standings_tenant FOREIGN KEY (tenant_id) REFERENCES foosball.tenants(id);
